PREFIX = {PE: 'PWR', W: 'IOT', R: 'ROB', PC: 'PCB', EA: 'EAI', HM: 'HML', V: 'VIS', RT: 'RTH', EC: 'ECE', SW: 'SW'}
POWER = {PE: 'Power Source (DC / AC Mains)', W: 'Power Supply (5V / Li-ion)', R: 'Battery Pack (7.4V / 12V)', PC: 'Board Power Input', EA: 'Power Supply (5V)', HM: 'Board Power (USB / 5V)', V: 'Power Supply (5V)', RT: 'Power Supply (3.3V / Battery)', EC: 'Power Source (DC / AC)'}
ADV = {
 PE: ['Measured efficiency and power quality', 'Simulation backed by hardware results', 'Applicable to EV, solar and industrial power'],
 W: ['Real-time remote monitoring', 'Low-cost, easily replicated hardware', 'Scales from one node to many'],
 R: ['Hands-free or autonomous operation', 'Modular so sensors and tools can be swapped', 'Demonstrable in a classroom or lab'],
 PC: ['Production-ready design files', 'Verified with design-rule and signal checks', 'Lower noise and EMI than breadboard builds'],
 EA: ['Runs on-device with no cloud dependency', 'Low latency and better privacy', 'Works at low power'],
 HM: ['Parallel hardware gives high throughput', 'Low power per inference', 'Reusable accelerator blocks'],
 V: ['Automates a manual, error-prone task', 'Works in real time on low-cost hardware', 'Produces logs for analysis'],
 RT: ['Deterministic real-time behaviour', 'Accurate and repeatable measurements', 'Clear alerts and data logging'],
 EC: ['Measured efficiency and power quality', 'Applicable to real energy systems', 'Backed by simulation and hardware results'],
 SW: ['No special hardware needed', 'Easy to extend with new data', 'Explainable results and dashboards'],
}

def listify(x): return [i for i in x if i]

out, seq = [], collections.Counter()
import re
used = set()
for p in P:
    d = p['d']; seq[d] += 1
    code = f"ISE-{PREFIX[d]}-{seq[d]:03d}"
    slug = re.sub(r'[^a-z0-9]+', '-', p['title'].lower()).strip('-')[:70].strip('-')
    base = slug; n = 2
    while slug in used: slug = f'{base}-{n}'; n += 1
    used.add(slug)
    hw = listify([p['ctrl']] + p['hwx']) if d != SW else []
    ins, outs, comms = p['ins'], p['outs'], p['comms']
    if d == SW:
        diagram = {'flow': ins + [o for o in outs]}
    else:
        diagram = {'power': POWER[d], 'controller': p['ctrl'], 'inputs': ins, 'outputs': outs}
        if comms: diagram['comms'] = comms
    if d == SW:
        proposed = f"{p['abstract']} The pipeline runs as: " + ' → '.join(diagram['flow']) + '.'
    else:
        proposed = f"{p['abstract']} The {p['ctrl']} reads {', '.join(ins[:3])}, processes the data on board and drives {', '.join(outs[:3])}" + (f", with {', '.join(comms)} for connectivity." if comms else '.')
    adv = ADV[d][:3] + (['Includes a verified IEEE base paper reference'] if p['ieee'] else ['Base paper and documentation shared on enquiry'])
    rec = dict(slug=slug, code=code, title=p['title'], domain=d, year='2025-26', featured=p['feat'], highValue=p['hv'],
               abstract=p['abstract'], existing=p['problem'], proposed=proposed, advantages=adv,
               applications=p['apps'], hardware=hw, software=p['sw'], diagram=diagram,
               ieee=({'title': I[p['ieee']][0], 'ref': I[p['ieee']][1]} if p['ieee'] else {'title': '', 'ref': ''}))
    out.append(rec)

root = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
with open(os.path.join(root, 'site/data/projects.json'), 'w') as f:
    json.dump(out, f, indent=1, ensure_ascii=False)
print(len(out), 'projects;', sum(r['highValue'] for r in out), 'high-value;', sum(bool(r['ieee']['title']) for r in out), 'with verified IEEE reference')
print(collections.Counter(r['domain'] for r in out))
